def parse_nested_parens_iter(paren_string: str) -> List[int]:
    """ Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parse_nested_parens_iter('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    output = []

    for parenthesis in paren_string.split():
        current_level: int = 0
        parenthesis = list(parenthesis)

        while len(parenthesis) != 0:
            ch = parenthesis.pop(0)
            if ch == "(":
                current_level += 1
            if ch == ")":
                current_level -= 1

    if not paren_string:
        return []
    elif paren_string.startswith('('):
        return [1] + parse_nested_parens(paren_string[1:])
    elif paren_string.endswith(')'):
        return [0] + parse_nested_parens(paren_string[:-1])
    else:
        return parse_nested_parens(paren_string[1:-1])


