def median(values: List[float]) -> float:
    """ Return the middle element of the dataset.
    >>> median([1, 2, 3, 4])
    2.5
    """
    sorted_values = sorted(values)
    length = len(sorted_values)
    if length % 2 == 0:
        return (sorted_values[length//2-1] + sorted_values[length//2])/2.0
    else:
        return float(sorted_values[length//2])

